const cfg = $('Config').first().json;
const intake = $('Normalise Intake').first().json;

const kbRows = $input.all()
  .map(i => i.json)
  .filter(r => r && (r.question || r.Question));

let kb = '';

kbRows.forEach(r => {
  kb += String(r.question || r.Question) + ' :: ' +
        String(r.answer || r.Answer || '') + '\n';
});

if (!kb) {
  kb = 'Clinic timings 10am to 7pm Monday to Saturday. Walk ins allowed but appointment preferred.';
}

const roster = String(cfg.doctor_roster || '');

const specs = [];

roster.split(';').forEach(pair => {
  const bits = pair.split('|');

  if (bits.length === 2) {
    specs.push(bits[1].trim());
  }
});

const phone = String(intake.patient_phone || '')
  .replace(/[^0-9]/g, '')
  .slice(-10);

const hist = $('Read Patient History')
  .all()
  .map(i => i.json)
  .filter(r => r && (r.record_id || r.patient_phone));

const mine = hist.filter(r =>
  String(r.patient_phone || '')
    .replace(/[^0-9]/g, '')
    .slice(-10) === phone &&
  phone.length === 10
);

let histText = 'No previous visit on record. Treat as a new patient.';

if (mine.length) {
  histText = '';

  mine.forEach(r => {
    histText +=
      String(r.appointment_slot || r.received_at || '') +
      ' | ' +
      String(r.specialty || '') +
      ' | ' +
      String(r.symptoms || '') +
      ' | seen by ' +
      String(r.doctor || '') +
      '\n';
  });
}

return [{
  json: {
    kb_text: kb,
    history_text: histText,
    visit_count: mine.length,
    is_returning: mine.length > 0,
    specialty_list: specs.join(', '),
    patient_name: intake.patient_name,
    message_text: intake.message_text
  }
}];

const raw = $input.first().json;
const body = raw.body || raw;

const pick = (a, b, c) => String(a || b || c || '').trim();

const name = pick(body.patient_name, body.name, body.from_name);
const phone = pick(body.patient_phone, body.phone, body.from);
const email = pick(body.patient_email, body.email, '');
const text = pick(body.message_text, body.message, body.text);
const channel = pick(body.channel, 'whatsapp', 'whatsapp');

const issues = [];

if (!text) {
  issues.push('Empty patient message');
}

if (!phone) {
  issues.push('No patient phone captured');
}

if (!name) {
  issues.push('No patient name captured');
}

if (!email) {
  issues.push('No patient email captured, reply could not be delivered by email');
}

return [{
  json: {
    patient_name: name || 'Unknown Patient',
    patient_phone: phone,
    patient_email: email,
    message_text: text,
    channel: channel,
    intake_issues: issues,
    intake_issue_count: issues.length
  }
}];

const t = $input.first().json;
const cfg = $('Config').first().json;
const intake = $('Normalise Intake').first().json;
const ctx = $('Assemble Context').first().json;
const hist = $('Read Patient History').all().map(i => i.json).filter(r => r && r.record_id);

const issues = [];

const allowedUrgency = ['emergency', 'urgent', 'routine'];
const allowedIntent = ['new_appointment', 'reschedule', 'cancel', 'medical_query', 'report_review', 'billing', 'other'];

let urgency = String(t.urgency || 'routine').trim().toLowerCase();
if (!allowedUrgency.includes(urgency)) {
  urgency = 'routine';
  issues.push('Invalid urgency from AI, defaulted to routine');
}

let intent = String(t.intent || 'other').trim().toLowerCase();
if (!allowedIntent.includes(intent)) {
  intent = 'other';
  issues.push('Invalid intent from AI, defaulted to other');
}

let specialty = String(t.specialty || 'General Medicine').trim();
const roster = String(cfg.doctor_roster || '');

const doctors = {};
roster.split(';').forEach(pair => {
  const bits = pair.split('|');
  if (bits.length === 2) {
    doctors[bits[1].trim()] = bits[0].trim();
  }
});

if (!doctors[specialty]) {
  specialty = 'General Medicine';
  issues.push('Specialty not found in doctor roster, defaulted to General Medicine');
}

const doctor = doctors[specialty] || 'General Medicine';

const now = new Date();
const openHour = Number(cfg.open_hour) || 10;
const closeHour = Number(cfg.close_hour) || 19;
const slotMinutes = Number(cfg.slot_minutes) || 20;

function fmtSlot(d) {
  const pad = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function nextOpen(d) {
  const x = new Date(d);
  if (x.getHours() < openHour) {
    x.setHours(openHour, 0, 0, 0);
  } else if (x.getHours() >= closeHour) {
    x.setDate(x.getDate() + 1);
    x.setHours(openHour, 0, 0, 0);
  }
  return x;
}

function roundToSlot(d) {
  const x = new Date(d);
  const mins = x.getMinutes();
  const rounded = Math.ceil(mins / slotMinutes) * slotMinutes;
  x.setMinutes(rounded, 0, 0);

  if (x.getHours() >= closeHour) {
    x.setDate(x.getDate() + 1);
    x.setHours(openHour, 0, 0, 0);
  }

  return x;
}

let slot;
let slotText;
let apptDate;

if (urgency === 'emergency') {
  slot = now;
  slotText = 'Immediate attention required';
  apptDate = fmtSlot(now).split(' ')[0];
} else if (urgency === 'urgent') {
  slot = new Date(now.getTime() + 2 * 60 * 60 * 1000);
  slot = nextOpen(slot);
  slot = roundToSlot(slot);
  slotText = fmtSlot(slot);
  apptDate = fmtSlot(slot).split(' ')[0];
} else {
  slot = new Date(now);
  slot.setDate(slot.getDate() + 1);
  slot.setHours(openHour, 0, 0, 0);
  slot = roundToSlot(slot);
  slotText = fmtSlot(slot);
  apptDate = fmtSlot(slot).split(' ')[0];
}

const stamp = now.toISOString().replace(/[-:.TZ]/g, '').slice(0, 14);

const phoneKey = String(intake.patient_phone || '')
  .replace(/[^0-9]/g, '')
  .slice(-10);

const dedupeMin = Number(cfg.dedupe_minutes) || 30;
const nowMs = now.getTime();

let isDuplicate = false;

hist.forEach(r => {
  const rp = String(r.patient_phone || '')
    .replace(/[^0-9]/g, '')
    .slice(-10);

  if (rp && rp === phoneKey) {
    const ts = Date.parse(
      String(r.received_at || '').trim().replace(' ', 'T') + 'Z'
    );

    if (
      !isNaN(ts) &&
      (nowMs - ts) < dedupeMin * 60000 &&
      (nowMs - ts) > -60000
    ) {
      isDuplicate = true;
    }
  }
});

let redFlags = Array.isArray(t.red_flags) ? t.red_flags : [];
let keyQ = Array.isArray(t.key_questions) ? t.key_questions : [];

let flagText = 'none';

if (redFlags.length) {
  flagText = redFlags.join('; ');
}

let qText = '';

keyQ.forEach(q => {
  qText += '- ' + String(q) + '\n';
});

const aiOk =
  !!t.intent &&
  !!t.urgency &&
  !!t.specialty;

return [{
  json: {
    record_id: 'PR' + stamp,
    appointment_id: 'AP' + stamp,
    received_at: fmtSlot(now),

    channel: intake.channel,
    patient_name: intake.patient_name,
    patient_phone: intake.patient_phone,
    patient_email: intake.patient_email,
    message_text: intake.message_text,

    intent: intent,
    urgency: urgency,
    is_emergency: urgency === 'emergency',

    red_flags: redFlags,
    red_flags_text: flagText,

    symptoms: String(t.symptoms || 'Not clearly stated'),
    duration: String(t.duration || 'unknown'),
    age_hint: String(t.age_hint || 'unknown'),
    language: String(t.language || 'english'),
    summary: String(t.summary || 'Patient enquiry received'),

    kb_answer: String(t.kb_answer || ''),

    key_questions: keyQ,
    key_questions_text:
      qText ||
      '- Confirm the exact onset and duration\n- Ask about any existing medication\n- Ask about known allergies\n',

    specialty: specialty,
    doctor: doctor,

    appointment_slot: slotText,
    appointment_date: apptDate,

    is_returning: !!ctx.is_returning,
    visit_count: Number(ctx.visit_count) || 0,
    history_text: ctx.history_text,

    clinic_name: cfg.clinic_name,
    clinic_phone: cfg.clinic_phone,
    clinic_address: cfg.clinic_address,
    doctor_email: cfg.doctor_email,

    ai_ok: aiOk,
    is_duplicate: isDuplicate,

    data_issues: issues,
    data_issue_count: issues.length,

    status: urgency === 'emergency' ? 'escalated' : 'booked'
  }
}];

