=You are the front desk of {{ $json.clinic_name || "the clinic" }} replying to a patient on WhatsApp. Be warm, short and respectful. You must NOT diagnose, must NOT name any illness and must NOT suggest any medicine.

PATIENT NAME: {{ $json.patient_name || "" }}
WHAT THEY WROTE: {{ $json.message_text || "" }}
LANGUAGE TO REPLY IN: {{ $json.language || "english" }}
URGENCY: {{ $json.urgency || "routine" }}
DOCTOR ASSIGNED: {{ $json.doctor || "" }} ({{ $json.specialty || "" }})
APPOINTMENT: {{ $json.appointment_slot || "" }}
CLINIC PHONE: {{ $json.clinic_phone || "" }}
CLINIC ADDRESS: {{ $json.clinic_address || "" }}
ADMIN ANSWER IF ANY: {{ $json.kb_answer || "none" }}

Return ONLY valid JSON, no markdown fences.

Keys:
greeting_line,
body_lines,
prep_lines,
closing_line.

greeting_line is one warm line addressing the patient by name.

body_lines is an array of 2 to 4 short lines confirming what happens next, naming the doctor and the appointment time.

If URGENCY is emergency, the FIRST body line must clearly tell them to come to the clinic immediately or call the clinic number now, and to go to the nearest emergency room if the person becomes worse. Do not soften it and do not name any condition.

prep_lines is an array of 2 or 3 short practical things to bring or do before the visit, such as previous reports, a list of current medicines, and coming 10 minutes early.

closing_line is one short reassuring line.

If LANGUAGE is hinglish, write naturally in Roman Hindi mixed with English the way Indian patients message.

If LANGUAGE is hindi, reply in simple Hindi written in Roman script.

Otherwise use plain Indian English.

No em-dashes anywhere.

OUTPUT FORMAT EXAMPLE:
The following is only an example of the required JSON structure. The patient name, doctor, appointment time, and other values shown are illustrative. Do not copy these example values unless they match the actual patient data provided above.

{
  "greeting_line": "Hello Rahul,",
  "body_lines": [
    "Your appointment has been scheduled with Dr Anil Menon.",
    "Your appointment time is 5:40 PM."
  ],
  "prep_lines": [
    "Please bring any previous medical reports.",
    "Please arrive 10 minutes before your appointment."
  ],
  "closing_line": "We look forward to seeing you."
}

parameters.jsCode:
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const d = $('Slot & Route Engine').first().json;
const r = $input.first().json;

const replyOk = !!r.greeting_line;

const greeting = r.greeting_line || ('Namaste ' + d.patient_name + ',');

const bodyLines =
  Array.isArray(r.body_lines) && r.body_lines.length
    ? r.body_lines
    : ['We have received your message and our team will contact you shortly.'];

const prepLines = Array.isArray(r.prep_lines) ? r.prep_lines : [];

const closing = r.closing_line || 'Thank you.';

const SLATE = '#0F2A3D';
const TEAL = '#0E7C7B';
const CREAM = '#F4F5F0';
const WHITE = '#FFFFFF';
const INK = '#1A1A1A';
const GREY = '#666666';
const RED = '#C0392B';
const AMBER = '#E67E22';

const isEmg = d.urgency === 'emergency';
const accent = isEmg
  ? RED
  : (d.urgency === 'urgent' ? AMBER : TEAL);

let bodyHtml = '';

bodyLines.forEach(l => {
  bodyHtml +=
    '<div style="font-size:15px;color:' + INK +
    ';line-height:1.6;margin-bottom:9px;">' +
    esc(l) +
    '</div>';
});

let prepHtml = '';

prepLines.forEach(l => {
  prepHtml +=
    '<li style="margin-bottom:6px;">' +
    esc(l) +
    '</li>';
});

let plain = greeting + '\n\n';

bodyLines.forEach(l => {
  plain += l + '\n';
});

if (prepLines.length) {
  plain += '\nPlease bring:\n';

  prepLines.forEach(l => {
    plain += '- ' + l + '\n';
  });
}

plain += '\n' + closing;

const banner = isEmg
  ? (
    '<tr><td style="background:' + RED + ';padding:12px 26px;">' +
    '<div style="color:#FFFFFF;font-size:13px;font-weight:bold;letter-spacing:1px;">' +
    'URGENT - PLEASE READ IMMEDIATELY' +
    '</div></td></tr>'
  )
  : '';

const html = '' +
'<div style="background:' + CREAM + ';padding:22px;font-family:Calibri,Arial,sans-serif;">' +

'<table width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto;background:' + WHITE + ';border-radius:10px;overflow:hidden;">' +

'<tr><td style="background:' + SLATE + ';padding:22px 26px;">' +
'<div style="color:#7FD1CE;font-size:11px;font-weight:bold;letter-spacing:3px;">APPOINTMENT UPDATE</div>' +
'<div style="color:' + WHITE + ';font-family:Georgia,serif;font-size:22px;font-weight:bold;margin-top:6px;">' +
esc(d.clinic_name) +
'</div>' +
'</td></tr>' +

banner +

'<tr><td style="padding:22px 26px 6px 26px;">' +
'<div style="font-size:16px;font-weight:bold;color:' + INK + ';margin-bottom:12px;">' +
esc(greeting) +
'</div>' +
bodyHtml +
'</td></tr>' +

'<tr><td style="padding:8px 26px;">' +

'<table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E4E4DC;border-radius:8px;border-left:4px solid ' + accent + ';">' +

'<tr>' +
'<td style="padding:12px 14px;font-size:12px;color:' + GREY + ';">Doctor</td>' +
'<td align="right" style="padding:12px 14px;font-size:14px;font-weight:bold;color:' + SLATE + ';">' +
esc(d.doctor) +
'</td>' +
'</tr>' +

'<tr>' +
'<td style="padding:12px 14px;font-size:12px;color:' + GREY + ';border-top:1px solid #E4E4DC;">Department</td>' +
'<td align="right" style="padding:12px 14px;font-size:14px;color:' + SLATE + ';border-top:1px solid #E4E4DC;">' +
esc(d.specialty) +
'</td>' +
'</tr>' +

'<tr>' +
'<td style="padding:12px 14px;font-size:12px;color:' + GREY + ';border-top:1px solid #E4E4DC;">Appointment</td>' +
'<td align="right" style="padding:12px 14px;font-size:14px;font-weight:bold;color:' + accent + ';border-top:1px solid #E4E4DC;">' +
esc(d.appointment_slot) +
'</td>' +
'</tr>' +

'<tr>' +
'<td style="padding:12px 14px;font-size:12px;color:' + GREY + ';border-top:1px solid #E4E4DC;">Reference</td>' +
'<td align="right" style="padding:12px 14px;font-size:13px;color:' + GREY + ';border-top:1px solid #E4E4DC;">' +
esc(d.appointment_id) +
'</td>' +
'</tr>' +

'</table>' +
'</td></tr>' +

(
  prepHtml
    ? (
      '<tr><td style="padding:16px 26px 4px 26px;">' +
      '<div style="font-size:13px;font-weight:bold;color:' + SLATE + ';margin-bottom:6px;">Please bring with you</div>' +
      '<ul style="font-size:14px;color:' + INK + ';line-height:1.5;margin:0;padding-left:20px;">' +
      prepHtml +
      '</ul>' +
      '</td></tr>'
    )
    : ''
) +

'<tr><td style="padding:16px 26px 20px 26px;">' +
'<div style="font-size:14px;color:' + INK + ';">' +
esc(closing) +
'</div>' +

'<div style="font-size:13px;color:' + GREY + ';margin-top:12px;">' +
esc(d.clinic_address) +
'<br>Call us: ' +
esc(d.clinic_phone) +
'</div>' +

'</td></tr>' +

'<tr><td style="background:' + CREAM + ';padding:12px 26px;">' +
'<div style="font-size:11px;color:' + GREY + ';line-height:1.45;">' +
'This message is an appointment confirmation only. It is not medical advice or a diagnosis. In an emergency please call ' +
esc(d.clinic_phone) +
' or go to the nearest emergency room.' +
'</div>' +
'</td></tr>' +

'</table>' +
'</div>';

return [
  {
    json: {
      patient_reply_html: html,
      patient_reply_text: plain,
      reply_ok: replyOk
    }
  }
];

