const text = $input.first().json.output[0].content[0].text;

if (!text) {
  throw new Error('No triage JSON found in ChatGPT output');
}

let triage;

try {
  triage = JSON.parse(text);
} catch (error) {
  throw new Error('ChatGPT returned invalid JSON: ' + error.message);
}

// Return the normalized JSON object
return [
  {
    json: {
      intent: triage.intent || "other",
      urgency: triage.urgency || "routine",
      specialty: triage.specialty || "General Medicine",
      red_flags: Array.isArray(triage.red_flags) ? triage.red_flags : [],
      symptoms: triage.symptoms || "",
      duration: triage.duration || "unknown",
      age_hint: triage.age_hint || "unknown",
      language: triage.language || "english",
      summary: triage.summary || "",
      kb_answer: triage.kb_answer || "",
      key_questions: Array.isArray(triage.key_questions)
        ? triage.key_questions
        : []
    }
  }
];

const text = $input.first().json.output[0].content[0].text;

if (!text) {
  throw new Error('No patient reply JSON found in ChatGPT output');
}

let reply;

try {
  reply = JSON.parse(text);
} catch (error) {
  throw new Error('ChatGPT returned invalid JSON: ' + error.message);
}

// Return the normalized JSON object
return [
  {
    json: {
      greeting_line: reply.greeting_line || '',
      body_lines: Array.isArray(reply.body_lines)
        ? reply.body_lines
        : [],
      prep_lines: Array.isArray(reply.prep_lines)
        ? reply.prep_lines
        : [],
      closing_line: reply.closing_line || ''
    }
  }
];

const text = $input.first().json.output[0].content[0].text;

if (!text) {
  throw new Error('No doctor brief JSON found in ChatGPT output');
}

let brief;

try {
  brief = JSON.parse(text);
} catch (error) {
  throw new Error('ChatGPT returned invalid JSON: ' + error.message);
}

// Return the normalized JSON object
return [
  {
    json: {
      chief_complaint: brief.chief_complaint || '',
      history_note: brief.history_note || '',
      observations: Array.isArray(brief.observations)
        ? brief.observations
        : [],
      questions_to_ask: Array.isArray(brief.questions_to_ask)
        ? brief.questions_to_ask
        : [],
      prep_note: brief.prep_note || '',
      caution_note: brief.caution_note || ''
    }
  }
];
